// Generates the Sass partials and the runtime token module from
// src/tokens/*.ts (#592).
//
//   npm run tokens:generate   write the generated files
//   npm run tokens:check      fail if any committed generated file is stale
//
// Runs on Node 22+ type-stripping, so imports use explicit .ts extensions and
// type-only imports use `import type`.
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import * as sass from 'sass';
import * as primitives from '../src/tokens/primitives.ts';
import * as semantic from '../src/tokens/semantic.ts';
import type { ColorValue } from '../src/tokens/primitives.ts';

// node:path rather than `new URL('..', import.meta.url)`: the unit tests
// import this under happy-dom, whose global URL can't resolve file: URLs.
const frontendDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

const SCSS_HEADER = `// GENERATED by scripts/generate-tokens.ts from src/tokens/ - do not edit.
// Edit src/tokens/*.ts, then run \`npm run tokens:generate\`.
`;

// --- Colours -----------------------------------------------------------

type Tree = string | number | Tree[] | { [key: string]: Tree } | ColorValue;

const COLOR_LITERAL = /^(#|rgba?\(|hsla?\()/;

const isRecipe = (value: unknown): value is Exclude<ColorValue, string> =>
  typeof value === 'object' && value !== null && 'kind' in value;

const isColor = (value: unknown): value is ColorValue =>
  isRecipe(value) || (typeof value === 'string' && COLOR_LITERAL.test(value));

function colorExpression(value: ColorValue): string {
  if (typeof value === 'string') return value;
  if (value.kind === 'adjust') {
    return `color.adjust(${colorExpression(value.base)}, $lightness: ${value.lightness}%)`;
  }
  return `rgba(${colorExpression(value.base)}, ${value.alpha})`;
}

interface ResolvedColor {
  /** Exactly what Sass serialises the colour as - emitted into the partials. */
  scss: string;
  /** Gamut-clipped hex, safe for native and the Tamagui runtime. */
  hex: string;
}

function collectColors(tree: unknown, into: Set<string>): void {
  if (isColor(tree)) {
    into.add(colorExpression(tree));
  } else if (Array.isArray(tree)) {
    tree.forEach((item) => collectColors(item, into));
  } else if (typeof tree === 'object' && tree !== null) {
    Object.values(tree).forEach((item) => collectColors(item, into));
  }
}

const hexByte = (n: number) => Math.round(n).toString(16).padStart(2, '0');

function toHex(sassColor: sass.SassColor): string {
  const rgb = sassColor.toSpace('rgb').toGamut({ method: 'clip' });
  const channels = ['red', 'green', 'blue'] as const;
  const hex = `#${channels.map((c) => hexByte(rgb.channel(c))).join('')}`;
  return rgb.alpha < 1 ? hex + hexByte(rgb.alpha * 255) : hex;
}

// Resolves every colour through the `sass` package itself, so derived values
// (color.adjust / rgba) are byte-identical to what the Sass build produced
// before the tokens moved to TS.
function resolveColors(expressions: string[]): Map<string, ResolvedColor> {
  const captured: sass.SassColor[] = [];
  const source = [
    "@use 'sass:color';",
    ...expressions.map((e, i) => `.t${i} { v: ${e}; w: capture(${i}, ${e}); }`),
  ].join('\n');
  const { css } = sass.compileString(source, {
    functions: {
      'capture($index, $color)': ([index, sassColor]) => {
        captured[index.assertNumber().value] = sassColor.assertColor();
        return sass.sassNull;
      },
    },
  });

  const serialised = new Map<number, string>();
  for (const match of css.matchAll(/\.t(\d+) \{\n {2}v: (.*);\n\}/g)) {
    serialised.set(Number(match[1]), match[2]);
  }

  return new Map(
    expressions.map((expression, i) => {
      const scss = serialised.get(i);
      if (scss === undefined) throw new Error(`Sass produced no value for ${expression}`);
      return [expression, { scss, hex: toHex(captured[i]) }];
    }),
  );
}

// --- Sass emission -----------------------------------------------------

const kebab = (name: string) =>
  name
    .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
    .replace(/([a-z])(\d)/g, '$1-$2')
    .toLowerCase();

const rem = (px: number) => `${px / 16}rem`;

// Scale keys ('050', '100', ...) must keep their numeric order - JS hoists
// canonical integer keys ('100') ahead of the rest ('050') in objects.
function orderedEntries<T>(object: Record<string, T>): [string, T][] {
  const entries = Object.entries(object);
  return entries.every(([key]) => /^\d+$/.test(key))
    ? entries.sort(([a], [b]) => Number(a) - Number(b))
    : entries;
}

type ScssValue = string | { [key: string]: ScssValue };

// Keys are emitted unquoted, exactly as authored: Sass parses `050` and
// `2xl` as numbers, and the existing map.get(..., 50) / map.get(..., 2xl)
// lookups only match unquoted keys.
function emitValue(value: ScssValue, depth = 0): string {
  if (typeof value === 'string') return value;
  const pad = '  '.repeat(depth);
  const entries = orderedEntries(value).map(
    ([key, item]) => `${pad}  ${kebab(key)}: ${emitValue(item, depth + 1)}`,
  );
  return `(\n${entries.join(',\n')}\n${pad})`;
}

const emitVariables = (variables: [string, ScssValue][]) =>
  variables.map(([name, value]) => `$${name}: ${emitValue(value)};`).join('\n');

function mapValues<T, U>(object: Record<string, T>, fn: (value: T) => U): Record<string, U> {
  return Object.fromEntries(Object.entries(object).map(([key, value]) => [key, fn(value)]));
}

// --- Outputs -----------------------------------------------------------

export function renderTokens(): Map<string, string> {
  const runtimeGroups = {
    color: primitives.color,
    scale: primitives.scale,
    spacing: primitives.spacing,
    typography: primitives.typography,
    breakpoints: primitives.breakpoints,
    zIndex: primitives.zIndex,
    duration: primitives.duration,
    easing: primitives.easing,
    semanticColor: semantic.semanticColor,
    textTone: semantic.textTone,
    buttonVariants: semantic.buttonVariants,
    listVariants: semantic.listVariants,
    semanticSpacing: semantic.semanticSpacing,
  };

  const expressions = new Set<string>();
  collectColors(runtimeGroups, expressions);
  const colors = resolveColors([...expressions]);

  const colorTree = (tree: Tree, pick: keyof ResolvedColor): Tree => {
    if (isColor(tree)) return colors.get(colorExpression(tree))![pick];
    if (Array.isArray(tree)) return tree.map((item) => colorTree(item, pick));
    if (typeof tree === 'object') return mapValues(tree, (item) => colorTree(item as Tree, pick));
    return tree;
  };
  const scssColors = (tree: object) => colorTree(tree as Tree, 'scss') as ScssValue;

  const lengths = (value: number | number[]) =>
    Array.isArray(value) ? value.map(rem).join(' ') : rem(value);

  const { typography } = primitives;
  const genericFamilies = new Set(['serif', 'sans-serif', 'monospace', 'cursive', 'system-ui']);
  const fontFamily = (families: string[]) =>
    `(${families.map((f) => (genericFamilies.has(f) ? f : `'${f}'`)).join(', ')})`;

  const files = new Map<string, string>();

  files.set(
    'src/styles/tokens/_colors.scss',
    emitVariables([
      ...Object.entries(scssColors(primitives.color) as Record<string, ScssValue>).map(
        ([key, value]): [string, ScssValue] => [`color-${key}`, value],
      ),
      ...Object.entries(primitives.scale).map(([key, value]): [string, ScssValue] => [
        `${key}-scale`,
        scssColors(value),
      ]),
    ]),
  );

  files.set(
    'src/styles/tokens/_spacing.scss',
    emitVariables([['spacing', mapValues(primitives.spacing, rem)]]),
  );

  files.set(
    'src/styles/tokens/_typography.scss',
    emitVariables([
      ['font-family', mapValues(typography.fontFamily, fontFamily)],
      ['font-size', mapValues(typography.fontSize, rem)],
      ['font-weight', mapValues(typography.fontWeight, String)],
      ['line-height', mapValues(typography.lineHeight, String)],
      ['letter-spacing', mapValues(typography.letterSpacing, (em) => (em === 0 ? '0' : `${em}em`))],
      ['text-transform', typography.textTransform],
      ['text-decoration', typography.textDecoration],
      ['text-align', typography.textAlign],
    ]),
  );

  files.set(
    'src/styles/base/_variables.scss',
    emitVariables([
      ['breakpoints', mapValues(primitives.breakpoints, (px) => `${px}px`)],
      ...Object.entries(primitives.zIndex).map(([key, value]): [string, ScssValue] => [
        `z-index-${key}`,
        String(value),
      ]),
      ...Object.entries(primitives.duration).map(([key, value]): [string, ScssValue] => [
        `duration-${key}`,
        `${value}ms`,
      ]),
      ...Object.entries(primitives.easing).map(([key, value]): [string, ScssValue] => [
        `easing-${key}`,
        value,
      ]),
    ]),
  );

  files.set(
    'src/styles/semantic/_colors.tokens.scss',
    emitVariables([
      ...Object.entries(scssColors(semantic.semanticColor) as Record<string, ScssValue>).map(
        ([key, value]): [string, ScssValue] => [kebab(key), value],
      ),
      ['text-tone', scssColors(semantic.textTone)],
      ['button-variants', scssColors(semantic.buttonVariants)],
      ['list-variants', scssColors(semantic.listVariants)],
    ]),
  );

  const spacingValue = (value: unknown): ScssValue => {
    if (typeof value === 'number' || Array.isArray(value)) return lengths(value as number[]);
    if (typeof value === 'string') return value;
    return mapValues(value as Record<string, unknown>, spacingValue);
  };
  files.set(
    'src/styles/semantic/_spacing.scss',
    emitVariables(
      Object.entries(semantic.semanticSpacing).map(([key, value]): [string, ScssValue] => [
        kebab(key),
        spacingValue(value),
      ]),
    ),
  );

  for (const [file, body] of files) files.set(file, `${SCSS_HEADER}\n${body}\n`);

  const runtime = Object.entries(runtimeGroups)
    .map(
      ([name, tree]) =>
        `export const ${name} = ${JSON.stringify(colorTree(tree as Tree, 'hex'), null, 2)} as const;`,
    )
    .join('\n\n');
  files.set(
    'src/tokens/resolved.generated.ts',
    `// GENERATED by scripts/generate-tokens.ts from src/tokens/ - do not edit.
// Edit src/tokens/*.ts, then run \`npm run tokens:generate\`.
//
// Every colour recipe is resolved to gamut-clipped hex; lengths are px.

${runtime}
`,
  );

  return files;
}

function main(check: boolean): void {
  const stale: string[] = [];
  for (const [file, content] of renderTokens()) {
    const target = path.join(frontendDir, file);
    let current: string | null = null;
    try {
      current = readFileSync(target, 'utf8');
    } catch {
      // Missing counts as stale.
    }
    if (current === content) continue;
    if (check) stale.push(file);
    else writeFileSync(target, content);
  }

  if (stale.length > 0) {
    console.error(
      `Generated token files are stale - run \`npm run tokens:generate\`:\n  ${stale.join('\n  ')}`,
    );
    process.exit(1);
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main(process.argv.includes('--check'));
}
